fn split_array(list: &Vec<i32>, l: usize) -> (Vec<i32>, Vec<i32>) {
    // `l` is guaranteed to be strictly between 0 and list.len()
    let mut first = Vec::with_capacity(l);
    let mut second = Vec::with_capacity(list.len() - l);

    // collect the first `l` elements
    for i in 0..l {
        first.push(list[i]);
    }

    // collect the remaining elements
    for i in l..list.len() {
        second.push(list[i]);
    }

    (first, second)
}

// Example usage and simple test:
fn main() {
    let v = vec![10, 20, 30, 40, 50];
    let (a, b) = split_array(&v, 2);
    assert_eq!(a, vec![10, 20]);
    assert_eq!(b, vec![30, 40, 50]);
    println!("split_array succeeded: {:?} | {:?}", a, b);
}